// Script to generate theme-presets.json from theme.js.backup
// Author: Generated by Kiro

const fs = require('fs');
const path = require('path');

const backupFilePath = path.join(__dirname, 'public', 'js', 'shared', 'theme.js.backup');
const outputFilePath = path.join(__dirname, 'public', 'data', 'theme-presets.json');

console.log('Reading backup file:', backupFilePath);

// Read the backup file
const fileContent = fs.readFileSync(backupFilePath, 'utf-8');

// Function to extract JavaScript object from code
function extractObject(content, varName) {
  // Find the variable declaration
  const regex = new RegExp(`const\\s+${varName}\\s*=\\s*({[\\s\\S]*?});`, 'm');
  const match = content.match(regex);

  if (!match) {
    throw new Error(`Could not find ${varName} in file`);
  }

  const objString = match[1];

  // Use eval to parse the JavaScript object (safe in this controlled context)
  try {
    return eval('(' + objString + ')');
  } catch (e) {
    console.error(`Error parsing ${varName}:`, e.message);
    throw e;
  }
}

console.log('Extracting theme data...');

// Extract all the objects
const defaultThemeLook = extractObject(fileContent, 'defaultThemeLook');
const classicThemePresets = extractObject(fileContent, 'classicThemePresets');
const classicPresetLabels = extractObject(fileContent, 'classicPresetLabels');
const classicPresetSwatches = extractObject(fileContent, 'classicPresetSwatches');
const songBoardThemePresets = extractObject(fileContent, 'songBoardThemePresets');
const songBoardPresetLabels = extractObject(fileContent, 'songBoardPresetLabels');
const songBoardPresetSwatches = extractObject(fileContent, 'songBoardPresetSwatches');

console.log('Building JSON structure...');

// Build the final JSON structure
const themePresetsData = {
  version: '1.0.0',
  default: defaultThemeLook,
  presets: {
    classic: classicThemePresets,
    classicLabels: classicPresetLabels,
    classicSwatches: classicPresetSwatches,
    songBoard: songBoardThemePresets,
    songBoardLabels: songBoardPresetLabels,
    songBoardSwatches: songBoardPresetSwatches
  }
};

// Ensure output directory exists
const outputDir = path.dirname(outputFilePath);
if (!fs.existsSync(outputDir)) {
  console.log('Creating output directory:', outputDir);
  fs.mkdirSync(outputDir, { recursive: true });
}

// Write the JSON file
console.log('Writing JSON file to:', outputFilePath);
fs.writeFileSync(outputFilePath, JSON.stringify(themePresetsData, null, 2), 'utf-8');

console.log('✓ Successfully generated theme-presets.json');
console.log('  - Default theme: ✓');
console.log('  - Classic presets:', Object.keys(classicThemePresets).length);
console.log('  - Song board presets:', Object.keys(songBoardThemePresets).length);
